def check_triangle(a, b, c):
    if a + b > c and b + c > a and c + a > b and a > 0 and b > 0 and c > 0:
        return True
    return False

def equation_holds(a, b, c):
    lhs = a**2 * b**2
    rhs = 2 * (a + b - c) * (b + c - a) * (c + a - b)
    return abs(lhs - rhs) < 1e-6

